// An item bundle is a line with no item of its own — the items sit under it.
// Picking one takes the bundle's code rather than an item code, and carries the
// bundle's items along so the invoice can rebuild the tree.
//
// The reference fields are read with ?. throughout: a bundle line has no UOM,
// tax rate or tariff of its own, so the plain dereferences would throw on it
// before any of the bundle handling ran.
(async () => {
  const currentPOArray = this.getValue(`item_array`);
  const selectedPOItem = arguments[0].$eventArgs[0];
  const referenceType = this.getValue(`reference_type`);

  console.log("arguments[0].$eventArgs[0]", arguments[0].$eventArgs[0]);
  const index = currentPOArray.findIndex(
    (item) => item.purchase_order_line_id === selectedPOItem.id
  );
  if (index !== -1) {
    currentPOArray.splice(index, 1);
  } else {
    const resPOItem = await db.collection('purchase_order_2ukyuanr_sub').doc(selectedPOItem.id).get();
    const poItemData = resPOItem?.data[0];

    currentPOArray.push({
      purchase_order_line_id: selectedPOItem.id,
      item: selectedPOItem.item_id,
      supplier: selectedPOItem.supplier_id,
      purchase_order: selectedPOItem.purchase_order_id,
      item_desc: selectedPOItem.item_desc,
      more_desc: selectedPOItem.more_desc,
      ordered_qty: selectedPOItem.quantity,
      invoice_qty: selectedPOItem.invoice_qty,
      received_qty: selectedPOItem.received_qty,
      item_uom: selectedPOItem.quantity_uom?.alt_uom_id,
      unit_price: selectedPOItem.unit_price,
      order_discount: selectedPOItem.discount,
      discount_uom: selectedPOItem.discount_uom,
      tax_rate_percent: selectedPOItem.tax_percent?.tax_rate_percent,
      tax_preference: selectedPOItem.tax_preference?.id,
      tax_inclusive: selectedPOItem.tax_inclusive,
      line_remark_1: selectedPOItem.line_remark_1,
      line_remark_2: selectedPOItem.line_remark_2,
      tariff_id: selectedPOItem.tariff_id?.id,
      further_description: poItemData?.further_description,
      item_bundle_id: selectedPOItem.item_bundle_id?.id || "",
      item_bundle_code: selectedPOItem.item_bundle_id?.ib_no || "",
      // The record read back from the collection carries the bundle's items as
      // a nested tree; the row off the list may not.
      children: poItemData?.children || selectedPOItem.children || [],
    });
  }

  console.log("currentPOArray", currentPOArray);

  const updatedPONumber = currentPOArray.map(
    (item) =>
      item.purchase_order.purchase_order_no +
      "\t" +
      (item.item_bundle_code || item.item?.material_code || "")
  );

  console.log("updatedPONumber", updatedPONumber.join(", "));

  this.setData({
    ...(!referenceType || referenceType === ""
      ? { [`reference_type`]: "Item - PO" }
      : {}),
    [`doc_number_array`]: updatedPONumber.join(`\n`),
    [`item_array`]: currentPOArray,
  });
})();

