  console.log("currentGRArray", currentGRArray);

  const updatedGRNumber = currentGRArray.map(
    (item) =>
      item.goods_receiving_number +
      "\t" +
      (item.item_bundle_code || item.item?.material_code || ""),
  );

  console.log("updatedGRNumber", updatedGRNumber.join(", "));

  this.setData({
    ...(!referenceType || referenceType === ""
      ? { [`reference_type`]: "Item - GR" }
      : {}),
    [`doc_number_array`]: updatedGRNumber.join(`\n`),
    [`item_array`]: currentGRArray,
  });
})();

